def leader(x):
	if P[x] == x:
		return P[x]
	if P[x] == x + 10 ** 5:
		return P[x]
	P[x] = leader(P[x])
	return P[x]

def same(x, y):
	return leader(x) == leader(y)

def canJoin(x, y):
	return not (leader(x) >= 10 ** 5 and leader(y) >= 10 ** 5)

def union(x, y):
	a = leader(x)
	b = leader(y)
	if a > b:
